import { Project, Screen, ElementProperties } from '../types/builder';

export function generateReactProjectCode(project: Project): Record<string, string> {
  const initialScreen = project.screens.find(s => s.isEntry) || project.screens[0];

  const screensCode = project.screens.map(screen => {
    return generateIndividualScreenComponent(screen);
  }).join('\n\n');

  const mainAppCode = `/**
 * Generated by FlowCraft Pro - Production React Mobile Prototype
 * Project: ${project.name}
 * Generated: ${new Date().toISOString()}
 */
import React, { useState } from 'react';
import { 
  ArrowRight, ShieldCheck, Lock, Key, ArrowDownLeft, Server, 
  Send, Home, CreditCard, Settings, Bell, Zap, Check, CheckCircle2, 
  Download, FileText, ChevronLeft, Search, Eye, EyeOff
} from 'lucide-react';

// Journey Flow Screen IDs
export type ScreenId = ${project.screens.map(s => `'${s.id}'`).join(' | ')};

export default function MobileApp() {
  const [currentScreen, setCurrentScreen] = useState<ScreenId>('${initialScreen?.id || project.screens[0].id}');
  const [history, setHistory] = useState<ScreenId[]>(['${initialScreen?.id || project.screens[0].id}']);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  const navigateTo = (target: ScreenId) => {
    setHistory(prev => [...prev, target]);
    setCurrentScreen(target);
  };

  const goBack = () => {
    if (history.length > 1) {
      const newHistory = [...history];
      newHistory.pop();
      setHistory(newHistory);
      setCurrentScreen(newHistory[newHistory.length - 1]);
    }
  };

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-slate-950 p-4 font-sans text-slate-100">
      {/* Mobile Device Frame */}
      <div className="relative mx-auto flex h-[844px] w-full max-w-[390px] flex-col overflow-hidden rounded-[48px] border-[8px] border-slate-800 bg-slate-900 shadow-2xl">
        {/* Dynamic Island / Top Notch */}
        <div className="relative z-50 flex items-center justify-between px-6 pt-3 pb-1 text-xs font-semibold text-slate-300">
          <span>9:41</span>
          <div className="h-6 w-28 rounded-full bg-black shadow-inner flex items-center justify-end px-2">
            <div className="h-2.5 w-2.5 rounded-full bg-emerald-500 animate-pulse"></div>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="text-[10px]">5G</span>
            <div className="h-2.5 w-4 rounded-sm border border-slate-300 p-0.5">
              <div className="h-full w-full bg-slate-200"></div>
            </div>
          </div>
        </div>

        {/* Screen Content Viewport */}
        <div className="relative flex-1 overflow-y-auto px-5 py-3">
          ${project.screens.map((screen, index) => `
          {currentScreen === '${screen.id}' && (
            <div key="${screen.id}" className="animate-in fade-in slide-in-from-right-4 duration-200">
              <Screen_${screen.id.replace(/[^a-zA-Z0-9]/g, '_')} 
                onNavigate={navigateTo} 
                onBack={goBack} 
                onToast={showToast} 
              />
            </div>
          )}`).join('')}
        </div>

        {/* In-app Toast Banner */}
        {toastMessage && (
          <div className="absolute top-14 left-4 right-4 z-50 rounded-xl bg-slate-800/95 border border-slate-700 p-3 shadow-lg backdrop-blur-md text-xs text-white flex items-center gap-2 animate-in slide-in-from-top-2">
            <Bell className="h-4 w-4 text-blue-400 shrink-0" />
            <span className="flex-1">{toastMessage}</span>
          </div>
        )}

        {/* Mobile Home Bar Indicator */}
        <div className="flex justify-center pb-2 pt-1">
          <div className="h-1 w-32 rounded-full bg-slate-600/60"></div>
        </div>
      </div>
    </div>
  );
}

${screensCode}
`;

  return {
    'src/App.tsx': mainAppCode,
    'src/main.tsx': `import React from 'react';
import ReactDOM from 'react-dom/client';
import MobileApp from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <MobileApp />
  </React.StrictMode>
);`,
    'package.json': JSON.stringify({
      name: project.name.toLowerCase().replace(/[^a-z0-9]/g, '-'),
      version: '1.0.0',
      private: true,
      type: 'module',
      scripts: {
        dev: 'vite',
        build: 'vite build',
        preview: 'vite preview',
      },
      dependencies: {
        react: '^19.0.0',
        'react-dom': '^19.0.0',
        'lucide-react': '^0.546.0',
      },
      devDependencies: {
        '@tailwindcss/vite': '^4.3.0',
        '@types/react': '^19.0.0',
        '@types/react-dom': '^19.0.0',
        '@vitejs/plugin-react': '^6.0.0',
        tailwindcss: '^4.3.0',
        typescript: '^5.7.0',
        vite: '^6.0.0',
      },
    }, null, 2),
    'README.md': `# ${project.name}

Exported from **FlowCraft Pro** interactive journey builder.

## Quickstart

\`\`\`bash
npm install
npm run dev
\`\`\`

Open [http://localhost:5173](http://localhost:5173) in your browser.

## Features
- Complete interactive journey flows with state machine transitions
- Responsive mobile hardware bezel simulator
- Dynamic forms with local validation
- Modular screen components styled with Tailwind CSS
`,
  };
}

function generateIndividualScreenComponent(screen: Screen): string {
  const componentName = `Screen_${screen.id.replace(/[^a-zA-Z0-9]/g, '_')}`;
  const annotationsComment = screen.annotations && screen.annotations.length > 0
    ? `/**
 * DEVELOPER CONTEXT & ARCHITECTURAL NOTES (${screen.annotations.length} items):
${screen.annotations.map(a => ` * - [${a.category.toUpperCase()}] ${a.title ? `${a.title}: ` : ''}${a.content} (Author: ${a.author || 'Product Architect'}${a.pinnedElementId ? ` | Pinned to: ${a.pinnedElementId}` : ''})`).join('\n')}
 */\n`
    : '';

  const elementsMarkup = screen.elements.map(el => {
    switch (el.type) {
      case 'header':
        return `      {/* App Bar Navigation */}
      <div className="mb-4 flex items-center justify-between border-b border-slate-800/80 pb-3">
        <div className="flex items-center gap-2">
          ${el.hasAction ? `
          <button onClick={() => onBack()} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-800 hover:text-white transition-colors">
            <ChevronLeft className="h-5 w-5" />
          </button>` : ''}
          <div>
            <h2 className="text-base font-bold text-white tracking-tight">${el.label}</h2>
            ${el.helperText ? `<p className="text-xs text-slate-400">${el.helperText}</p>` : ''}
          </div>
        </div>
        <button onClick={() => onToast('Notifications up to date')} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 hover:text-white">
          <Bell className="h-4 w-4" />
        </button>
      </div>`;

      case 'button': {
        const variantClass = el.variant === 'primary'
          ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-500/20'
          : el.variant === 'outline'
          ? 'border border-slate-700 bg-slate-800/60 hover:bg-slate-800 text-slate-200'
          : el.variant === 'ghost'
          ? 'text-slate-400 hover:text-white hover:bg-slate-800/40'
          : 'bg-emerald-600 text-white';

        let clickHandler = '() => {}';
        if (el.hasAction) {
          if (el.actionType === 'navigate' && el.targetScreenId) {
            clickHandler = `() => onNavigate('${el.targetScreenId}')`;
          } else if (el.actionType === 'back') {
            clickHandler = `() => onBack()`;
          } else if (el.actionType === 'toast') {
            clickHandler = `() => onToast('${el.toastMessage || 'Action triggered'}')`;
          }
        }

        return `      {/* Button: ${el.name} */}
      <button 
        onClick={${clickHandler}}
        className="flex w-full items-center justify-center gap-2 rounded-xl px-4 py-3.5 text-sm font-semibold transition-all active:scale-[0.98] ${variantClass} mb-3"
      >
        <span>${el.label}</span>
        <ArrowRight className="h-4 w-4" />
      </button>`;
      }

      case 'input':
        return `      {/* Input: ${el.name} */}
      <div className="mb-3">
        <label className="mb-1 block text-xs font-medium text-slate-300">${el.label}</label>
        <div className="relative">
          <input 
            type="${el.inputType || 'text'}" 
            defaultValue="${el.value || ''}"
            placeholder="${el.placeholder || ''}"
            className="w-full rounded-xl border border-slate-700 bg-slate-800/80 px-3.5 py-2.5 text-sm text-white placeholder-slate-500 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
          />
        </div>
        ${el.helperText ? `<p className="mt-1 text-[11px] text-slate-400">${el.helperText}</p>` : ''}
      </div>`;

      case 'card':
        return `      {/* Card: ${el.name} */}
      <div className="mb-3 rounded-2xl border border-slate-800 bg-slate-800/50 p-4 backdrop-blur-sm">
        <div className="flex items-start gap-3">
          <div className="rounded-xl bg-blue-500/10 p-2 text-blue-400">
            <ShieldCheck className="h-5 w-5" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-white">${el.label}</h3>
            ${el.helperText ? `<p className="mt-1 text-xs leading-relaxed text-slate-400">${el.helperText}</p>` : ''}
          </div>
        </div>
      </div>`;

      case 'metric':
        return `      {/* Metric Display: ${el.name} */}
      <div className="mb-3 rounded-2xl border border-slate-800 bg-gradient-to-br from-slate-800/90 to-slate-900/90 p-4">
        <span className="text-xs font-medium uppercase tracking-wider text-slate-400">${el.label}</span>
        <div className="mt-1 font-mono text-2xl font-bold tracking-tight text-white tabular-nums">${el.metricValue || '$0.00'}</div>
        ${el.metricChange ? `<div className="mt-1 text-xs font-semibold text-emerald-400">${el.metricChange}</div>` : ''}
      </div>`;

      case 'list_item':
        return `      {/* Transaction List Item: ${el.name} */}
      <div className="mb-2 flex items-center justify-between rounded-xl border border-slate-800/60 bg-slate-800/30 p-3 hover:bg-slate-800/50 transition-colors">
        <div className="flex items-center gap-3">
          <div className="rounded-lg bg-slate-700/60 p-2 text-slate-300">
            <ArrowDownLeft className="h-4 w-4" />
          </div>
          <div>
            <p className="text-xs font-semibold text-white">${el.label}</p>
            ${el.helperText ? `<p className="text-[11px] text-slate-400">${el.helperText}</p>` : ''}
          </div>
        </div>
        <span className="font-mono text-xs font-bold text-white tabular-nums">${el.metricValue || ''}</span>
      </div>`;

      case 'carousel':
      case 'asset_slider': {
        const slides = el.carouselSlides || el.sliderSlides || [];
        const timing = el.carouselInterval || el.sliderInterval || 3000;
        const speed = el.carouselAnimationSpeed || 500;
        return `      {/* Interactive Banner Image Carousel: ${el.name} */}
      <div className="relative mb-4 overflow-hidden rounded-2xl border border-slate-800 bg-slate-950 shadow-lg" style={{ height: '${el.carouselHeight || el.sliderHeight || 190}px' }}>
        <div className="flex h-full transition-transform duration-${speed} ease-out">
          ${slides.map((s, idx) => `
          <div key="${s.id || idx}" className="relative h-full w-full shrink-0 cursor-pointer" onClick={() => onNavigate('${s.targetScreenId || el.targetScreenId || ''}')}>
            <img src="${s.imageUrl}" alt="${s.title || ''}" className="h-full w-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-950/30 to-transparent p-3 flex flex-col justify-end">
              <span className="text-xs font-bold text-white">${s.title || ''}</span>
              ${(s as any).subtitle || (s as any).caption ? `<span className="text-[10px] text-slate-300">${(s as any).subtitle || (s as any).caption}</span>` : ''}
            </div>
          </div>`).join('')}
        </div>
      </div>`;
      }

      case 'video_player':
      case 'media_placeholder': {
        const videoSrc = el.videoUrl || (el.imageUrl?.match(/\.(mp4|webm|mov)$/i) ? el.imageUrl : '') || '';
        if (el.type === 'video_player' || el.mediaType === 'video' || videoSrc) {
          return `      {/* 16:9 Streaming Video Player: ${el.name} */}
      <div className="relative mb-4 aspect-video w-full overflow-hidden rounded-2xl border border-slate-800 bg-slate-950 shadow-md">
        <video 
          src="${videoSrc || 'https://assets.mixkit.co/videos/preview/mixkit-digital-animation-of-screens-4192-large.mp4'}"
          controls={${el.videoControls ?? true}}
          autoPlay={${el.videoAutoplay ?? false}}
          loop={${el.videoLoop ?? true}}
          muted={${el.videoMuted ?? true}}
          className="h-full w-full object-cover"
        />
        ${el.mediaCaption ? `<div className="p-2 text-[10px] text-slate-400 font-mono">${el.mediaCaption}</div>` : ''}
      </div>`;
        }
        return `      {/* Media Placeholder: ${el.name} */}
      <div className="relative mb-4 aspect-video w-full overflow-hidden rounded-2xl border border-slate-800 bg-slate-900 flex items-center justify-center p-4">
        <span className="text-xs text-slate-400 font-medium">${el.label}</span>
      </div>`;
      }

      case 'image_banner':
        return `      {/* Hero Visual */}
      <div className="relative mb-4 h-40 w-full overflow-hidden rounded-2xl border border-slate-800">
        <img 
          src="${el.imageUrl || 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=800'}" 
          alt="${el.label}" 
          className="h-full w-full object-cover" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-950/40 to-transparent p-4 flex flex-col justify-end">
          <span className="text-sm font-bold text-white">${el.label}</span>
          ${el.helperText ? `<span className="text-xs text-slate-300">${el.helperText}</span>` : ''}
        </div>
      </div>`;

      case 'badge':
        return `      {/* Badge: ${el.name} */}
      <div className="mb-3 flex items-center gap-2 rounded-lg bg-emerald-500/10 border border-emerald-500/20 px-3 py-2 text-xs font-medium text-emerald-400">
        <ShieldCheck className="h-4 w-4 shrink-0" />
        <span>${el.label}</span>
      </div>`;

      case 'toggle':
        return `      {/* Toggle: ${el.name} */}
      <div className="mb-3 flex items-center justify-between rounded-xl border border-slate-800 bg-slate-800/40 p-3">
        <div>
          <span className="text-xs font-medium text-white">${el.label}</span>
          ${el.helperText ? `<p className="text-[11px] text-slate-400">${el.helperText}</p>` : ''}
        </div>
        <div className="relative h-6 w-11 cursor-pointer rounded-full bg-blue-600 p-0.5">
          <div className="h-5 w-5 rounded-full bg-white transition-transform translate-x-5 shadow"></div>
        </div>
      </div>`;

      case 'tabbar':
        return `      {/* Bottom Tab Bar */}
      <div className="mt-4 flex items-center justify-around border-t border-slate-800 pt-2 pb-1 text-slate-400">
        <button onClick={() => onNavigate('screen_dashboard')} className="flex flex-col items-center gap-1 text-blue-400">
          <Home className="h-4 w-4" />
          <span className="text-[10px] font-medium">Home</span>
        </button>
        <button onClick={() => onNavigate('screen_transfer')} className="flex flex-col items-center gap-1 hover:text-white">
          <Send className="h-4 w-4" />
          <span className="text-[10px] font-medium">Transfer</span>
        </button>
        <button onClick={() => onToast('Cards vault coming soon')} className="flex flex-col items-center gap-1 hover:text-white">
          <CreditCard className="h-4 w-4" />
          <span className="text-[10px] font-medium">Cards</span>
        </button>
      </div>`;

      case 'divider':
        return `      {/* Divider */}
      <div className="my-3 flex items-center gap-3">
        <div className="h-px flex-1 bg-slate-800"></div>
        <span className="text-[11px] text-slate-500">${el.label || 'or'}</span>
        <div className="h-px flex-1 bg-slate-800"></div>
      </div>`;

      default:
        return '';
    }
  }).join('\n\n');

  return `${annotationsComment}function ${componentName}({ onNavigate, onBack, onToast }: { onNavigate: (id: ScreenId) => void; onBack: () => void; onToast: (msg: string) => void }) {
  return (
    <div className="flex flex-col pb-4">
${elementsMarkup}
    </div>
  );
}`;
}
